android.extraProguardRules:
# Heimlig keep rules for R8, added with versionCode 96.
# Everything listed here is reached by NAME at runtime, not through a call R8 can see.
# Removing or renaming any of it gives the classic failure mode: the build succeeds, the
# app starts, and one single feature dies at runtime in the release build only.

# expo-notifications ships android/proguard-rules.pro but does NOT wire it up through
# consumerProguardFiles (checked in its build.gradle), so unlike every other Expo module
# its rules do not arrive on their own.
-keep class expo.modules.notifications.** { *; }

# Home screen widget. The provider and its receiver are named as strings in
# AndroidManifest.xml and instantiated by the OS, outside the app process.
-keep class com.reactnativeandroidwidget.** { *; }
-keep class * extends android.appwidget.AppWidgetProvider { *; }

# Play Billing. The purchase listener is called back by the Play Store app across a
# binder, and the response objects are deserialised by field name.
-keep class com.android.billingclient.** { *; }
-keep class expo.modules.iap.** { *; }

# Sentry needs its own classes kept and needs line numbers to survive, otherwise every
# stack trace it uploads becomes unreadable, which would remove the one tool for
# diagnosing whatever else R8 breaks.
-keep class io.sentry.** { *; }
-keepattributes SourceFile,LineNumberTable,*Annotation*,Signature,InnerClasses,EnclosingMethod
-renamesourcefileattribute SourceFile

# React Native native modules and view managers are resolved by name from JavaScript,
# so the class names have to survive.
-keep class com.reactnativecommunity.asyncstorage.** { *; }
-keep class com.reactnativecommunity.webview.** { *; }
-keep class com.swmansion.** { *; }

# Camera and image picker are covered in principle by expo-modules-core's consumer
# rules, kept explicitly because both own an Activity result contract that the system
# re-creates by name after the process was killed in the background.
-keep class expo.modules.camera.** { *; }
-keep class expo.modules.imagepicker.** { *; }

# Optional transitive dependencies that are not on the runtime classpath.
-dontwarn okhttp3.**
-dontwarn okio.**
